head.script:
scwin.trigger1_onclick = function (e) {
	for (var i = 0; i < 4; i++) {
		windowContainer1.createWindow("sub" + i, null, "/sample/common_link/windowContainer_Fixed_WPF-1727_(WSQ-2853)_sub.xml", "", null, "existWindow", null, null);
	}
};
scwin.trigger2_onclick = function (e) {
	windowContainer1.fixWindow($p.id + "windowContainer1_subWindow2");
};
scwin.trigger3_onclick = function (e) {
	windowContainer1.unfixWindow($p.id + "windowContainer1_subWindow2");
};
// parameter type: 10번째 인자(options)에 fixed (원본 샘플은 9번째 자리에 넣어 고정되지 않았음 → API 가이드 순서로 수정)
scwin.trigger4_onclick = function (e) {
	windowContainer1.createWindow("sub4", null, "/sample/common_link/windowContainer_Fixed_WPF-1727_(WSQ-2853)_sub.xml", "", null, "newWindow", null, null, null, {
		fixed: true
	});
};
// json type
scwin.trigger5_onclick = function (e) {
	windowContainer1.createWindow({
		title: "sub5",
		src: "/sample/common_link/windowContainer_Fixed_WPF-1727_(WSQ-2853)_sub.xml",
		openAction: "newWindow",
		fixed: true
	});
};
